#!/usr/bin/env node
// greet: prints a greeting, or its version with --version.

const VERSION = '1.0.0';

const args = process.argv.slice(2);

if (args[0] === '--version') {
  console.log(`greet ${VERSION}`);
} else if (args.length === 0) {
  console.log('Hello, world!');
} else {
  console.log(`Hello, ${args.join(' ')}!`);
}

